"""Export the frozen, fitted design-only V as a C++23 header."""
import sys
sys.dont_write_bytecode=True
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
frozen=json.loads((HERE/'FROZEN.json').read_text())
name=frozen['selected_model']
s=json.loads((HERE/'models'/(name+'.final.json')).read_text())
assert s['mode'] in ('stationary32','stationary','compact','fast','static')
code='''#pragma once
// Frozen fitted V; generated by emit_cpp.py. Lower means fewer expected moves.
// Contents: Coefficients; Prediction; Adapter from the solver's DesignState.
#include "design_features.hpp"
namespace deval {
// ==== Coefficients ====
struct ModelTerm { const char* name; double coefficient; };
'''
code+=f'inline constexpr double kIntercept={s["intercept"]:.17g};\n'
code+=f'inline constexpr std::array<ModelTerm,{len(s["feature_names"])}> kTerms{{{{\n'
for n,c in zip(s['feature_names'],s['coefficients']):code+=f'    {{"{n}",{c:.17g}}},\n'
code+='}};\n'
code+='''// ==== Prediction ====
// Construct once and share its design-independent table across candidates.
class DesignValue {
    GenericTable generic_;
public:
    double operator()(State state) const {
        state.prepare();
        auto features=static_features(state,generic_);
'''
if s['mode']=='stationary32':code+='        add_stationary_features(features,state,32,2);\n'
elif s['mode']=='stationary':code+='        add_stationary_features(features,state,16,4);\n'
elif s['mode']=='compact':code+='        add_filler_features(features,state,4.,{1.,2.2},32);\n'
elif s['mode']=='fast':code+='        add_filler_features(features,state,2.,{1.6},32);\n'
code+='''        double value=kIntercept;
        for(const auto& term:kTerms)value+=term.coefficient*features.at(term.name);
        return value;
    }
    // ==== Adapter from the solver's DesignState ====
    template<class DesignState> double from_design(const DesignState& d) const {
        State s;s.M=d.M;s.G=d.G;s.H=d.H;
        for(int t=0;t<P;++t)s.target[t]=d.A[t],s.ded[t]=d.ded[t];
        for(int k=0;k<K;++k) {
            s.opaque[k]=d.papers[k].opaque;s.black[k]=d.papers[k].black;s.col[k]=d.columns[k];
        }
        for(int c=0;c<s.H;++c)s.handle[c]=d.handle[c];
        for(int j=0;j<s.G;++j) {
            s.edge[j]={d.edge[j].first,d.edge[j].second};s.polarity[j]=d.polarity[j];
        }
        return (*this)(s);
    }
};
} // namespace deval
'''
(HERE/'value.hpp').write_text(code)
print('exported',name,'with',len(s['feature_names']),'terms')
